    function openInfoPanel(d){ $("#infoTitle").textContent=d.t; $("#infoBody").innerHTML=d.b; openOverlay("infoOverlay"); }
    document.addEventListener("click",e=>{
      const so=e.target.closest("[data-social]");
      if(so){ const d=SOCIALS[so.dataset.social]; if(d){ sfx.click(); openInfoPanel(d); } return; }
      const su=e.target.closest("[data-support]");
      if(su){ sfx.click(); openOverlay("supportOverlay"); if(!$("#chatLog").children.length) pushChat("agent","Hey there — Betvora Support here. Ask me about deposits, bonuses, VIP or any game."); return; }
      const wa=e.target.closest("[data-wallet]");
      if(wa){ sfx.click(); requireAuth(openWallet); }
    });
    $$("[data-info]").forEach(b=>b.addEventListener("click",()=>{
      const d=INFO[b.dataset.info]; if(!d) return;
      $("#infoTitle").textContent=d.t; $("#infoBody").innerHTML=d.b; openOverlay("infoOverlay"); sfx.click();
    }));
